			text: 'Pokud je plocha druhého pístu 100× větší než prvního, výsledná síla se…',
			odpovedi: ['znásobí 100×', 'zmenší 100×', 'nezmění'],
			vysvetleni: 'Kolikrát větší plocha, tolikrát větší síla — 100× větší píst dá 100× větší sílu.',
